#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    int totalWins = 0, maxSegment = 0;
    int start = 0, end = 0;

    // Replace all "__" with "_"
    while (s.find("__") != string::npos) {
        size_t pos = s.find("__");
        s.replace(pos, 2, "_");
    }
    n = (int)s.length();

    // Process initial segment if it starts with '('
    if (!s.empty() && s[start] == '(') {
        end = start;
        while (end < n && s[end] != ')') end++;
        if (end < n && s[end] == ')') {
            string inside = s.substr(start + 1, end - (start + 1));
            if (inside.find('_') == string::npos && !inside.empty()) {
                totalWins++;
            } else {
                int count = 1;
                for (char c : inside) {
                    if (c == '_') count++;
                }
                totalWins += count;
            }
            start = end + 1;
        }
    }

    // Process all other segments enclosed in parentheses
    for (int idx = 0; idx < n; idx++) {
        if (s[idx] == '(') {
            int closeIdx = idx;
            while (closeIdx < n && s[closeIdx] != ')') closeIdx++;
            if (closeIdx < n && s[closeIdx] == ')') {
                string inside = s.substr(idx + 1, closeIdx - (idx + 1));
                if (inside.find('_') == string::npos && !inside.empty()) {
                    totalWins++;
                } else {
                    int count = 1;
                    for (char c : inside) {
                        if (c == '_') count++;
                    }
                    totalWins += count;
                }
                idx = closeIdx;
            }
        }
    }

    // Remove all parentheses and their contents
    while (true) {
        size_t openPos = s.find('(');
        size_t closePos = s.find(')');
        if (openPos == string::npos || closePos == string::npos || closePos < openPos) break;
        s.replace(openPos, closePos - openPos + 1, "_");
    }

    // Split by '_'
    stringstream ss(s);
    string segment;
    while (getline(ss, segment, '_')) {
        if ((int)segment.length() > maxSegment)
            maxSegment = segment.length();
    }

    cout << maxSegment << " " << totalWins << "\n";

    return 0;
}
